def _runs(seq, color):
    out = []
    i = 0
    while i < len(seq):
        if seq[i] != color:
            i += 1
            continue
        j = i + 1
        while j < len(seq) and seq[j] == color:
            j += 1
        if j - i >= 2:
            out.append((i, j))
        i = j
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(v == c for row in grid for v in row) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])

    # Find equal-length segments on opposite edges.
    pair = None
    for vertical in (True, False):
        for color in range(10):
            if color == bg:
                continue
            if vertical:
                first = _runs([grid[r][0] for r in range(h)], color)
                second = _runs([grid[r][w - 1] for r in range(h)], color)
            else:
                first = _runs(grid[0], color)
                second = _runs(grid[h - 1], color)
            for a in first:
                for b in second:
                    if a[1] - a[0] == b[1] - b[0]:
                        pair = (vertical, color, a, b)
                        break
                if pair:
                    break
            if pair:
                break
        if pair:
            break
    if pair is None:
        return [row[:] for row in grid]

    vertical, rail_color, a, b = pair
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != rail_color]

    for r, c, color in markers:
        pos = r if vertical else c
        source = next((run for run in (a, b) if run[0] <= pos < run[1]), None)
        if source is None:
            continue
        target = b if source is a else a
        mapped = target[0] + (pos - source[0])
        if vertical:
            ray = range(c - 1, 0, -1) if source is a else range(c + 1, w - 1)
            for cc in ray:
                if out[r][cc] == bg:
                    out[r][cc] = color
            if 0 <= mapped < h:
                stripe_cols = range(w) if len(markers) > 1 else range(1, w - 1)
                for cc in stripe_cols:
                    if out[mapped][cc] == bg:
                        out[mapped][cc] = color
        else:
            ray = range(r - 1, 0, -1) if source is a else range(r + 1, h - 1)
            for rr in ray:
                if out[rr][c] == bg:
                    out[rr][c] = color
            if 0 <= mapped < w:
                stripe_rows = range(h) if len(markers) > 1 else range(1, h - 1)
                for rr in stripe_rows:
                    if out[rr][mapped] == bg:
                        out[rr][mapped] = color
        out[r][c] = 4
    return out
